import{_ as e,o as t,c as s,a3 as i}from"./chunks/framework.BLaSdaBb.js";const k=JSON.parse('{"title":"升级与迁移","description":"","frontmatter":{},"headers":[],"relativePath":"backend/upgrade.md","filePath":"backend/upgrade.md","lastUpdated":1786258579000}'),d={name:"backend/upgrade.md"};function n(o,a,r,l,p,c){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="升级与迁移" tabindex="-1">升级与迁移 <a class="header-anchor" href="#升级与迁移" aria-label="Permalink to &quot;升级与迁移&quot;">​</a></h1><p>BasicApp 已接入 <a href="https://framework.docs.xihanfun.com/guide/upgrade" target="_blank" rel="noreferrer">XiHan.Framework.Upgrade</a> 的版本状态、迁移台账、多租户分发、租约锁与维护模式扩展，并在 <code>WebHost/UpdateScripts</code> 保存前向 SQL 脚本。本页区分<strong>已经接线的基础能力</strong>与<strong>当前尚未接线的执行入口</strong>，避免把“引擎可做什么”误写成“应用启动时已经做了什么”。</p><h2 id="当前结论" tabindex="-1">当前结论 <a class="header-anchor" href="#当前结论" aria-label="Permalink to &quot;当前结论&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>当前状态</th></tr></thead><tbody><tr><td>Framework Upgrade 模块与引擎</td><td>已注册</td></tr><tr><td><code>SysVersion</code> 版本状态</td><td>已落库，每个数据库各自维护</td></tr><tr><td><code>SysMigrationHistory</code> 台账存储与查询页</td><td>已接线；只有引擎实际执行后才会产生记录</td></tr><tr><td>文件系统脚本发现</td><td>已接入，目录为 <code>UpdateScripts</code></td></tr><tr><td>平台库 + 独立租户库分发</td><td>已实现</td></tr><tr><td>数据库租约锁</td><td>已实现</td></tr><tr><td>维护模式中间件</td><td>已实现</td></tr><tr><td>BasicApp 调用 <code>IUpgradeCoordinator.StartAsync()</code> / <code>IUpgradeEngine.ExecuteAsync()</code></td><td><strong>当前没有调用入口</strong></td></tr><tr><td>启动时自动执行 SQL</td><td><strong>当前不会发生</strong></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title"><code>EnableAutoCheckOnStartup</code> 目前不等于“自动执行迁移”</p><p><code>XiHanUpgradeModule.OnPostApplicationInitializationAsync</code> 当前只调用 <code>IUpgradeStatusService.EnsureInitializedAsync()</code>，作用是确保版本行存在；它不会调用升级协调器或引擎。BasicApp 源码中也没有其它 <code>IUpgradeCoordinator</code> / <code>IUpgradeEngine</code> 调用方。</p><p>因此当前版本即使 <code>EnableAutoCheckOnStartup=true</code>，也只会初始化状态，不会执行 <code>UpdateScripts</code>、不会进入维护模式，也不会因 SQL 失败阻止启动。需要上线自动迁移前，必须先补一个明确的执行入口并定义失败策略。</p></div><h2 id="代码落点" tabindex="-1">代码落点 <a class="header-anchor" href="#代码落点" aria-label="Permalink to &quot;代码落点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>职责</th><th>位置 / 类型</th></tr></thead><tbody><tr><td>框架模块</td><td><code>XiHanBasicAppCoreModule</code> 依赖 <code>XiHanUpgradeModule</code></td></tr><tr><td>版本与台账存储</td><td><code>SaasUpgradeVersionStore</code></td></tr><tr><td>数据库租约锁</td><td><code>SaasUpgradeLockProvider</code></td></tr><tr><td>多租户列表</td><td><code>SaasUpgradeTenantProvider</code></td></tr><tr><td>SQL 执行</td><td><code>SaasUpgradeMigrationExecutor</code></td></tr><tr><td>维护模式</td><td><code>BasicAppUpgradeMaintenanceModeManager</code> + <code>MaintenanceModeMiddleware</code></td></tr><tr><td>脚本目录</td><td><code>backend/src/main/XiHan.BasicApp.WebHost/UpdateScripts</code></td></tr><tr><td>版本页面</td><td><code>/setting/version</code></td></tr><tr><td>升级记录页面</td><td><code>/log/migration</code></td></tr></tbody></table><p>BasicApp 在 <code>AddSaasDomainServices()</code> 中注册四个数据库适配器，使单服务解析优先使用业务实现：版本与台账写入业务库，SQL 由当前租户上下文解析出的 SqlSugar 客户端执行。</p><h2 id="全新数据库与存量数据库" tabindex="-1">全新数据库与存量数据库 <a class="header-anchor" href="#全新数据库与存量数据库" aria-label="Permalink to &quot;全新数据库与存量数据库&quot;">​</a></h2><p>两条路径职责不同：</p><table tabindex="0"><thead><tr><th>场景</th><th>机制</th><th>负责内容</th></tr></thead><tbody><tr><td>全新数据库</td><td>SqlSugar CodeFirst + Seeder</td><td>建库、建表、系统基线与演示数据</td></tr><tr><td>存量数据库</td><td>Upgrade + <code>UpdateScripts</code></td><td>增删列、索引变化、数据修复与版本推进</td></tr></tbody></table><p><code>DbInitializer</code> 对已存在的表不会自动补列。实体结构变更如果只改 C#、不写前向 SQL，存量库会在查询时出现 <code>column does not exist</code> 一类错误。</p><h2 id="脚本约定" tabindex="-1">脚本约定 <a class="header-anchor" href="#脚本约定" aria-label="Permalink to &quot;脚本约定&quot;">​</a></h2><p>当前目录内已有：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UpdateScripts/</span></span>
<span class="line"><span>├── 3.10.0.sql</span></span>
<span class="line"><span>├── 3.10.1.sql</span></span>
<span class="line"><span>└── README.md</span></span></code></pre></div><p>规则：</p><ol><li>文件名使用语义版本号，如 <code>3.10.2.sql</code>，并与 <code>backend/props/version.props</code> 一起升级。</li><li>当前脚本使用 <strong>PostgreSQL 方言</strong>；文档中的 MySQL / MariaDB 支持主要指 ORM 与首次 CodeFirst，不代表现有升级脚本可直接跨库运行。</li><li>PostgreSQL 标识符使用小写且不加引号，匹配 SqlSugar 实际创建的表列名。</li><li>尽量用 <code>IF EXISTS</code> / <code>IF NOT EXISTS</code> 写成可重试脚本。</li><li>一个版本内若存在多个脚本，引擎按脚本名排序；版本之间按语义版本升序执行。</li><li>先在生产数据副本验证脚本、备份与回滚方案，再发布应用。</li></ol><p>示例：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 3.10.2.sql</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sys_example</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ADD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COLUMN </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IF</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> EXISTS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> remark </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">varchar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> INDEX</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> IF</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> EXISTS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ix_sys_example_tenant_id</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sys_example (tenant_id);</span></span></code></pre></div><h2 id="引擎被调用后的流程" tabindex="-1">引擎被调用后的流程 <a class="header-anchor" href="#引擎被调用后的流程" aria-label="Permalink to &quot;引擎被调用后的流程&quot;">​</a></h2><p>执行入口接通后，<code>UpgradeEngine</code> 对每个目标数据库执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>解析应用版本与脚本</span></span>
<span class="line"><span>  → 读取/创建 SysVersion</span></span>
<span class="line"><span>  → 比较 DbVersion 与最新脚本版本</span></span>
<span class="line"><span>  → 获取数据库租约锁</span></span>
<span class="line"><span>  → 标记 IsUpgrading</span></span>
<span class="line"><span>  → 进入维护模式</span></span>
<span class="line"><span>  → 按版本和脚本名执行未成功记录过的脚本</span></span>
<span class="line"><span>  → 写 SysMigrationHistory 并推进 DbVersion</span></span>
<span class="line"><span>  → 更新 AppVersion</span></span>
<span class="line"><span>  → 退出维护模式并释放锁</span></span></code></pre></div><p><code>HasMigrationHistoryAsync(version, scriptName)</code> 只跳过已有<strong>成功</strong>记录的脚本；失败记录不会阻止下一次重试。</p><h3 id="多租户" tabindex="-1">多租户 <a class="header-anchor" href="#多租户" aria-label="Permalink to &quot;多租户&quot;">​</a></h3><p><code>EnableMultiTenantIsolation=true</code> 时，目标顺序是：</p><ol><li>平台库；</li><li><code>IsolationMode=Database</code> 且 <code>ConfigStatus=Configured</code> 的租户独立库。</li></ol><p>字段隔离租户与平台共库，不重复执行。每个独立库都有自己的 <code>SysVersion</code> 与 <code>SysMigrationHistory</code>，数据库版本可以独立追踪。</p><h3 id="租约锁" tabindex="-1">租约锁 <a class="header-anchor" href="#租约锁" aria-label="Permalink to &quot;租约锁&quot;">​</a></h3><p><code>SaasUpgradeLockProvider</code> 通过条件更新 <code>SysVersion.IsUpgrading</code> 抢占执行权，并用 <code>UpgradeStartTime + LockExpirySeconds</code> 回收崩溃节点遗留的锁。它不是 Redis 锁，也不是 PostgreSQL 会话级建议锁。</p><p><code>PrimaryNodeName</code> 非空时，只有节点名完全匹配的实例会执行；留空时所有节点均可竞争数据库租约。<code>NodeName</code> 留空则由机器名与应用实例 ID 组合生成。</p><h3 id="维护模式" tabindex="-1">维护模式 <a class="header-anchor" href="#维护模式" aria-label="Permalink to &quot;维护模式&quot;">​</a></h3><p>引擎进入维护模式后，本节点的大部分请求返回：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">503</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;系统正在升级维护，请稍后重试。&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>响应带 <code>Retry-After: 30</code>。<code>/health</code> 与 <code>/.well-known/</code> 被放行，保证编排探针和 OIDC 发现/JWKS 可继续访问。</p><div class="warning custom-block"><p class="custom-block-title">维护状态只在当前进程内生效</p><p><code>MaintenanceModeState</code> 是进程内单例。多副本部署时，执行迁移的节点进入维护模式，不会自动让其它节点一起停流。若迁移与旧版本不兼容，应在网关或发布编排层统一摘流，不能只依赖该中间件。</p></div><h2 id="执行入口怎么选" tabindex="-1">执行入口怎么选 <a class="header-anchor" href="#执行入口怎么选" aria-label="Permalink to &quot;执行入口怎么选&quot;">​</a></h2><p>当前应用没有执行入口。补接线时应先明确策略：</p><table tabindex="0"><thead><tr><th>策略</th><th>适用场景</th><th>注意</th></tr></thead><tbody><tr><td>发布流水线独立迁移步骤</td><td>生产推荐</td><td>迁移成功后再放应用流量，边界最清晰</td></tr><tr><td>宿主启动时同步调用 <code>IUpgradeEngine.ExecuteAsync()</code></td><td>单体或严格启动门禁</td><td>必须检查 <code>UpgradeStartResult.Status</code>，失败时显式终止启动</td></tr><tr><td>管理端调用 <code>IUpgradeCoordinator.StartAsync()</code></td><td>人工触发</td><td>协调器后台运行且只记日志，不能天然形成启动失败门禁</td></tr></tbody></table><p>不要在多个位置同时触发。无论选择哪种方式，都要保证只有一个可审计入口，并测试多节点竞争、脚本失败、进程中断和重复执行。</p><h2 id="页面与权限" tabindex="-1">页面与权限 <a class="header-anchor" href="#页面与权限" aria-label="Permalink to &quot;页面与权限&quot;">​</a></h2><ul><li><code>/setting/version</code>：查看 <code>SysVersion</code>，只读；写端点已移除。</li><li><code>/log/migration</code>：查看脚本版本、脚本名、成功状态、执行时间、节点与错误信息。</li><li>两页读取都要求 <code>saas:version:read</code>；版本列表导出使用 <code>saas:version:export</code>。</li></ul><p>页面展示的是当前租户上下文解析到的数据库状态。排查独立租户库时要先确认当前租户，不能只看平台库记录。</p><h2 id="发布检查清单" tabindex="-1">发布检查清单 <a class="header-anchor" href="#发布检查清单" aria-label="Permalink to &quot;发布检查清单&quot;">​</a></h2><ol><li>抬高应用版本，并新增同版本或更低的必要 SQL 脚本。</li><li>确认脚本为 PostgreSQL 小写无引号标识符，且可安全重试。</li><li>在生产副本依次验证升级、重复执行和失败恢复。</li><li>备份平台库与全部数据库隔离租户库。</li><li>确认生产环境实际使用的升级触发入口；当前源码默认没有入口。</li><li>多节点发布时确认 <code>NodeName</code> / <code>PrimaryNodeName</code>、租约时长与统一摘流方案。</li><li>升级后检查 <code>/setting/version</code>、<code>/log/migration</code>、应用日志与关键业务查询。</li></ol><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./database">数据库配置</a>：CodeFirst、连接与存量结构变更</li><li><a href="./health-observability">健康检查与可观测性</a>：维护窗口仍放行的 <code>/health</code></li><li><a href="./../configuration#xihan-upgrade">配置参考</a>：<code>XiHan:Upgrade</code> 字段</li><li><a href="./../deployment">部署</a>：发布、进程守护与生产配置</li><li><a href="https://framework.docs.xihanfun.com/guide/upgrade" target="_blank" rel="noreferrer">Framework 升级与迁移</a>：引擎抽象与通用流程</li></ul>`,46)])])}const g=e(d,[["render",n]]);export{k as __pageData,g as default};
